<section class="gamification-list"><header><h1><?php echo $this->lang('Tournaments') ?></h1></header><div class="gamification-grid"><?php foreach ($tournaments as $row): ?><article class="gamification-card"><span class="gamification-badge"><?php echo utf8_htmlentities($row['status']) ?></span><h2><a href="<?php echo url('tournaments/'.$row['tournament_id'].'/'.$row['slug']) ?>"><?php echo utf8_htmlentities($row['title']) ?></a></h2><p><?php echo utf8_htmlentities($row['location']) ?></p><time><?php echo utf8_htmlentities($row['starts_at'] ?? '') ?></time><small><?php echo $this->lang('%d participants', (int)$row['participant_count']) ?></small></article><?php endforeach ?></div></section>
